// ============================================================================
// Config & Safety Gate
// Reads ONLY environment variables and resolves a fail-safe configuration.
// Secrets never enter item data: only presence booleans leave this node.
//
//   * Safe-ON flags  (SANDBOX_MODE, DRY_RUN) turn OFF only on false/0/no/off.
//   * Safe-OFF flags (SLACK_MUTATIONS_ENABLED, HUBSPOT_MUTATIONS_ENABLED,
//     AI_ENABLED, ...) turn ON only on true/1/yes/on.
//   * Typos keep the safe value. Blocked $env access => all safe defaults.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;
function readEnv(key) {
  try {
    const v = $env[key];
    return v === undefined || v === null ? '' : String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (k, d = '') => readEnv(k) || d;
const safeOn = (k) => !FALSY.includes(readEnv(k).toLowerCase());
const safeOff = (k) => TRUTHY.includes(readEnv(k).toLowerCase());
const list = (k, d = '') => (readEnv(k) || d).split(',').map((s) => s.trim()).filter(Boolean);
const num = (k, d, min, max) => {
  const n = Number(readEnv(k).replace(/[, _]/g, ''));
  return readEnv(k) === '' || !Number.isFinite(n) ? d : Math.min(max, Math.max(min, n));
};
const SYNTHETIC_PORTAL_ID = '99000001';
const EMAIL_RE = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;
const SLACK_USER_RE = /^[UW][A-Z0-9]{2,20}$/;

const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const slackMutationsEnabled = safeOff('SLACK_MUTATIONS_ENABLED');
const hubspotMutationsEnabled = safeOff('HUBSPOT_MUTATIONS_ENABLED');
const aiEnabled = safeOff('AI_ENABLED');

const hasHubspotToken = readEnv('HUBSPOT_ACCESS_TOKEN') !== '';
const hasSlackToken = readEnv('SLACK_BOT_TOKEN') !== '';
const hasAiKey = readEnv('AI_API_KEY') !== '';
const hasWebhookSecret = readEnv('WEBHOOK_SHARED_SECRET').length >= 16;

const configuredPortalId = str('HUBSPOT_PORTAL_ID');
const portalId = sandboxMode ? SYNTHETIC_PORTAL_ID : configuredPortalId;
if (!sandboxMode) {
  const problems = [];
  if (!hasHubspotToken) problems.push('HUBSPOT_ACCESS_TOKEN is not set');
  if (!/^\d{1,12}$/.test(configuredPortalId)) problems.push('HUBSPOT_PORTAL_ID must be a numeric HubSpot portal ID');
  if (problems.length) {
    throw new Error('Live mode (SANDBOX_MODE=false) refused: ' + problems.join('; ') + '. Fix the variables or keep SANDBOX_MODE=true.');
  }
}

// ---- Threshold & eligibility ------------------------------------------------
const threshold = {
  amount: num('ARR_THRESHOLD', 50000, 0, 1e12),
  property: str('ARR_PROPERTY', 'amount').replace(/[^a-z0-9_]/gi, '') || 'amount',
  currency: str('THRESHOLD_CURRENCY', 'USD').toUpperCase(),
  allowCurrencyMismatch: safeOff('ALLOW_CURRENCY_MISMATCH'),
  eligiblePipelines: list('ELIGIBLE_PIPELINES'),
  eligibleStages: list('ELIGIBLE_DEAL_STAGES'),
  excludedStages: list('EXCLUDED_DEAL_STAGES', 'closedwon,closedlost'),
  triggerProperties: list('TRIGGER_PROPERTIES', 'amount,dealstage,hs_arr,hs_acv,pipeline'),
};

// ---- HubSpot ---------------------------------------------------------------
const stampProps = {
  channelId: str('HUBSPOT_STAMP_CHANNEL_ID_PROPERTY', 'war_room_slack_channel_id').replace(/[^a-z0-9_]/gi, ''),
  channelUrl: str('HUBSPOT_STAMP_CHANNEL_URL_PROPERTY', 'war_room_slack_channel_url').replace(/[^a-z0-9_]/gi, ''),
  createdAt: str('HUBSPOT_STAMP_CREATED_AT_PROPERTY', 'war_room_created_at').replace(/[^a-z0-9_]/gi, ''),
};
const hubspotApiBase = str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, '');
const dealProperties = [...new Set([
  'dealname', 'amount', 'deal_currency_code', 'dealstage', 'pipeline', 'closedate', 'hubspot_owner_id',
  'hs_arr', 'hs_acv', 'hs_next_step', 'hs_priority', 'description', threshold.property,
  stampProps.channelId, stampProps.channelUrl, stampProps.createdAt,
].filter(Boolean))];

// ---- Slack -----------------------------------------------------------------
const leadershipIdsRaw = list('LEADERSHIP_SLACK_USER_IDS');
const leadershipEmailsRaw = list('LEADERSHIP_EMAILS');
const warnings = [];
const leadershipSlackUserIds = leadershipIdsRaw.filter((id) => SLACK_USER_RE.test(id));
const leadershipEmails = leadershipEmailsRaw.filter((e) => EMAIL_RE.test(e)).map((e) => e.toLowerCase());
if (leadershipSlackUserIds.length !== leadershipIdsRaw.length) warnings.push('Some LEADERSHIP_SLACK_USER_IDS were not valid Slack user IDs and were ignored');
if (leadershipEmails.length !== leadershipEmailsRaw.length) warnings.push('Some LEADERSHIP_EMAILS were not valid emails and were ignored');

let channelPrefix = str('CHANNEL_PREFIX', 'deal-').toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 20);
if (!channelPrefix) channelPrefix = 'deal-';
if (!/[-_]$/.test(channelPrefix)) channelPrefix += '-';

// ---- Gates -----------------------------------------------------------------
const hubspotStampBlockers = [];
if (sandboxMode) hubspotStampBlockers.push('SANDBOX_MODE=true');
if (dryRun) hubspotStampBlockers.push('DRY_RUN=true');
if (!hubspotMutationsEnabled) hubspotStampBlockers.push('HUBSPOT_MUTATIONS_ENABLED is not true');
if (!stampProps.channelId) hubspotStampBlockers.push('HUBSPOT_STAMP_CHANNEL_ID_PROPERTY is empty');
if (envBlocked) hubspotStampBlockers.push('n8n blocked $env access');
const hubspotStampAllowed = hubspotStampBlockers.length === 0;

const allowSlackWithoutStamp = safeOff('ALLOW_SLACK_WITHOUT_HUBSPOT_STAMP');
const slackBlockers = [];
if (sandboxMode) slackBlockers.push('SANDBOX_MODE=true (synthetic fixture run)');
if (dryRun) slackBlockers.push('DRY_RUN=true');
if (!slackMutationsEnabled) slackBlockers.push('SLACK_MUTATIONS_ENABLED is not true');
if (!hasSlackToken) slackBlockers.push('SLACK_BOT_TOKEN is not set');
if (!hubspotStampAllowed && !allowSlackWithoutStamp) {
  slackBlockers.push('HubSpot stamping is off, so idempotency cannot be guaranteed (enable HUBSPOT_MUTATIONS_ENABLED or set ALLOW_SLACK_WITHOUT_HUBSPOT_STAMP=true)');
}
if (envBlocked) slackBlockers.push('n8n blocked $env access');
const slackAllowed = slackBlockers.length === 0;

const aiModel = str('AI_MODEL');
const aiApiBase = str('AI_API_BASE_URL', 'https://api.openai.com/v1').replace(/\/+$/, '');
const aiBlockers = [];
if (!aiEnabled) aiBlockers.push('AI_ENABLED is not true');
if (sandboxMode) aiBlockers.push('SANDBOX_MODE=true (no external calls)');
if (!hasAiKey) aiBlockers.push('AI_API_KEY is not set');
if (!aiModel) aiBlockers.push('AI_MODEL is not set');
if (!/^https:\/\//.test(aiApiBase)) aiBlockers.push('AI_API_BASE_URL must use https');
const aiAllowed = aiBlockers.length === 0;

const now = (() => {
  const o = str('NOW_OVERRIDE');
  return o && !Number.isNaN(Date.parse(o)) ? new Date(o).toISOString() : new Date().toISOString();
})();

const config = {
  runId: 'wr-' + now.replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 8),
  now,
  envBlocked,
  sandboxMode,
  dryRun,
  portalId,
  threshold,
  hubspot: {
    apiBase: hubspotApiBase,
    appBase: str('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com').replace(/\/+$/, ''),
    hasToken: hasHubspotToken,
    dealProperties,
    stampProps,
    mutationsEnabled: hubspotMutationsEnabled,
    stampAllowed: hubspotStampAllowed,
    stampBlockers: hubspotStampBlockers,
    testDealId: str('TEST_DEAL_ID').replace(/\D/g, ''),
    stageLabels: Object.fromEntries(list('DEAL_STAGE_LABELS').map((p) => p.split(':').map((x) => x.trim())).filter((p) => p.length === 2 && p[0])),
  },
  context: {
    maxContacts: num('MAX_CONTACTS', 50, 1, 100),
    maxEngagementsPerType: num('MAX_ENGAGEMENTS_PER_TYPE', 10, 1, 50),
    briefIncludeContactNames: safeOn('BRIEF_INCLUDE_CONTACT_NAMES'),
  },
  slack: {
    hasToken: hasSlackToken,
    mutationsEnabled: slackMutationsEnabled,
    allowed: slackAllowed,
    blockers: slackBlockers,
    channelPrefix,
    channelPrivate: safeOn('CHANNEL_PRIVATE'),
    stripLegalSuffixes: safeOn('SLUG_STRIP_LEGAL_SUFFIXES'),
    inviteDealOwner: safeOn('INVITE_DEAL_OWNER'),
    leadershipSlackUserIds,
    leadershipEmails,
    maxInvitees: num('MAX_INVITEES', 25, 1, 100),
    workspaceUrl: str('SLACK_WORKSPACE_URL').replace(/\/+$/, ''),
    apiBase: str('SLACK_API_BASE_URL', 'https://slack.com/api').replace(/\/+$/, ''),
  },
  ai: {
    enabled: aiEnabled,
    allowed: aiAllowed,
    blockers: aiBlockers,
    model: aiModel,
    url: `${aiApiBase}/chat/completions`,
    jsonMode: safeOn('AI_JSON_MODE'),
    includeContactNames: safeOff('AI_INCLUDE_CONTACT_NAMES'),
    maxInputChars: num('AI_MAX_INPUT_CHARS', 6000, 1000, 30000),
  },
  webhook: {
    hasSecret: hasWebhookSecret,
    maxDealsPerExecution: num('MAX_DEALS_PER_EXECUTION', 10, 1, 50),
  },
  idempotency: {
    lockTtlMinutes: num('IDEMPOTENCY_LOCK_TTL_MINUTES', 30, 1, 1440),
  },
  warnings,
};

const safetyDecisions = [
  `Mode: ${sandboxMode ? 'SANDBOX (synthetic fixture, zero network calls)' : 'LIVE (HubSpot reads)'}`,
  `Dry run: ${dryRun}`,
  `Slack provisioning: ${slackAllowed ? 'ARMED' : 'BLOCKED'}`,
  `HubSpot war-room stamp: ${hubspotStampAllowed ? 'ARMED' : 'BLOCKED'}`,
  `AI synthesis: ${aiAllowed ? 'ENABLED (' + aiModel + ')' : 'OFF (deterministic brief)'}`,
  `Threshold: ${threshold.currency} ${threshold.amount} on "${threshold.property}"`,
];

// ---- Trigger payload: verify the webhook secret HERE, then strip sensitive
// headers and the whole query string so the secret never travels downstream.
function constantTimeEqual(a, b) {
  const x = String(a || '');
  const y = String(b || '');
  const len = Math.max(x.length, y.length);
  let diff = x.length ^ y.length;
  for (let i = 0; i < len; i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0 && x.length > 0;
}
const SENSITIVE_HEADERS = new Set(['x-war-room-secret', 'authorization', 'cookie', 'x-hubspot-signature', 'x-hubspot-signature-v3', 'proxy-authorization']);
const trigger = $input.all().map((i) => {
  const j = i.json || {};
  if (!(j && typeof j === 'object' && 'body' in j && 'headers' in j)) return j;
  const headers = Object.fromEntries(Object.entries(j.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  // Header (preferred) or ?war_room_secret= on the target URL (HubSpot app
  // webhook subscriptions cannot send custom headers).
  const query = j.query && typeof j.query === 'object' ? j.query : {};
  const provided = headers['x-war-room-secret'] !== undefined ? headers['x-war-room-secret'] : query.war_room_secret;
  const webhookAuth = {
    headerPresent: provided !== undefined && provided !== '',
    valid: hasWebhookSecret && constantTimeEqual(provided, readEnv('WEBHOOK_SHARED_SECRET')),
  };
  const safeHeaders = Object.fromEntries(Object.entries(headers).filter(([k]) => !SENSITIVE_HEADERS.has(k)));
  return { headers: safeHeaders, body: j.body, query: {}, webhookAuth };
});
return [{ json: { config, safetyDecisions, trigger } }];

// ============================================================================
// Parse & Authenticate Trigger Event
// Turns the trigger payload into one item per candidate deal ID.
//   * Manual trigger, sandbox  -> one placeholder item (fixture supplies deals)
//   * Manual trigger, live     -> TEST_DEAL_ID (required)
//   * Webhook, live            -> requires the x-war-room-secret header check
//                                 done by Config & Safety Gate to have passed
// Accepts both HubSpot webhook-subscription batches (array of events) and the
// HubSpot workflow "Send a webhook" action (single object).
// ============================================================================
const { config, trigger } = $('Config & Safety Gate').first().json;
const first = trigger[0] || {};
const isWebhook = first && typeof first === 'object' && 'body' in first && 'headers' in first;

const out = (dealId, extra = {}) => ({
  json: {
    dealId: String(dealId),
    source: isWebhook ? 'webhook' : 'manual',
    dealUrl: `${config.hubspot.apiBase}/crm/v3/objects/deals/${encodeURIComponent(String(dealId))}` +
      `?properties=${encodeURIComponent(config.hubspot.dealProperties.join(','))}` +
      `&associations=${encodeURIComponent('companies,contacts,calls,meetings,notes')}`,
    ...extra,
  },
});

if (config.sandboxMode) {
  return [{ json: { dealId: '*fixture*', source: isWebhook ? 'webhook (sandbox: fixture used)' : 'manual', dealUrl: null } }];
}

if (!isWebhook) {
  if (!config.hubspot.testDealId) {
    throw new Error('Manual live run needs TEST_DEAL_ID (a numeric HubSpot deal ID in the configured portal).');
  }
  return [out(config.hubspot.testDealId)];
}

// ---- Webhook authentication (fail closed) ----------------------------------
if (!config.webhook.hasSecret) {
  throw new Error('Webhook rejected: WEBHOOK_SHARED_SECRET (16+ chars) must be set in live mode.');
}
if (!first.webhookAuth || first.webhookAuth.valid !== true) {
  throw new Error('Webhook rejected: missing or invalid x-war-room-secret header (or war_room_secret query parameter).');
}

// ---- Payload parsing --------------------------------------------------------
const body = first.body;
const events = Array.isArray(body) ? body : body && typeof body === 'object' ? [body] : [];
const ids = [];
const ignored = [];
for (const ev of events) {
  if (ev.portalId !== undefined && String(ev.portalId) !== String(config.portalId)) {
    ignored.push(`event for portal ${ev.portalId} ignored (expected ${config.portalId})`);
    continue;
  }
  if (ev.subscriptionType) {
    const t = String(ev.subscriptionType);
    if (!/^deal\.(propertyChange|creation)$/.test(t)) { ignored.push(`subscriptionType ${t} ignored`); continue; }
    if (t === 'deal.propertyChange' && ev.propertyName && !config.threshold.triggerProperties.includes(ev.propertyName)) {
      ignored.push(`propertyName ${ev.propertyName} ignored`);
      continue;
    }
  }
  const id = ev.objectId ?? ev.hs_object_id ?? ev.dealId ?? (ev.properties && (ev.properties.hs_object_id?.value ?? ev.properties.hs_object_id));
  if (id !== undefined && /^\d{1,20}$/.test(String(id))) ids.push(String(id));
  else ignored.push('event without a numeric deal ID ignored');
}
const unique = [...new Set(ids)].slice(0, config.webhook.maxDealsPerExecution);
// Returning no items ends the execution quietly (nothing to do).
return unique.map((id) => out(id, { ignoredEvents: ignored.length }));

// ============================================================================
// Load Synthetic Deal Context  (SANDBOX_MODE=true path - ZERO network calls)
// The embedded object is identical to
// sample-payloads/enterprise-deal-context-fixture.json (verified by the
// simulator). Emits one item per fixture deal so every gating rule is shown.
// ============================================================================
const FIXTURE = {
